1	<!doctype html>
2	<html lang="en">
3	  <head>
4	    <meta charset="utf-8" />
5	    <title>Todos</title>
6	  </head>
7	  <body>
8	    <h1>Todos</h1>
9	    <form id="add">
10	      <label for="title">New todo</label>
11	      <input id="title" name="title" required />
12	      <button type="submit">Add</button>
13	    </form>
14	    <ul id="list"></ul>
15	    <script type="module">
16	      const list = document.getElementById("list");
17	      async function render() {
18	        const todos = await (await fetch("/api/todos")).json();
19	        list.replaceChildren(
20	          ...todos.map((t) => {
21	            const li = document.createElement("li");
22	            const box = document.createElement("input");
23	            box.type = "checkbox";
24	            box.checked = t.done;
25	            box.ariaLabel = t.title;
26	            box.onchange = async () => {
27	              await fetch(`/api/todos/${t.id}`, { method: "PATCH" });
28	              render();
29	            };
30	            li.append(box, ` ${t.title}`);
31	            return li;
32	          }),
33	        );
34	      }
35	      document.getElementById("add").onsubmit = async (e) => {
36	        e.preventDefault();
37	        const input = document.getElementById("title");
38	        await fetch("/api/todos", { method: "POST", body: JSON.stringify({ title: input.value }) });
39	        input.value = "";
40	        render();
41	      };
42	      render();
43	    </script>
44	  </body>
45	</html>
